param()
$ErrorActionPreference='Stop';$root='C:\Sirket\ERP\evidence\ERP-CRM-EXPAND-20261009\private\infra';$out=Join-Path $root 'business-effects-baseline-capture.json';if(Test-Path -LiteralPath $out){throw 'BUSINESS_EFFECTS_BASELINE_EXISTS'}
$cfg=Get-Content -LiteralPath 'C:\Sirket\ERP\runtime\ERP-CRM-EXPAND-20261009\shared-copy-config.json' -Raw|ConvertFrom-Json;if($cfg.database-cne 'MELISA_ERP_CRM_SHARED_TEST_20261009_02'-or$cfg.server-cne 'Semih\MELISADEV'-or$cfg.businessReadyPerformanceRevision.version-ne 2-or$cfg.businessEffectsPerformanceRevision){throw 'BUSINESS_EFFECTS_BASELINE_TARGET'}
$b=[Data.SqlClient.SqlConnectionStringBuilder]::new();$b['Data Source']=$cfg.server;$b['Initial Catalog']=$cfg.database;$b['User ID']=$cfg.sqlUser;$b['Password']=$cfg.sqlPassword;$b['Encrypt']=$false;$b['Application Name']='BUSINESS-EFFECTS-BASELINE-SELECT';$cn=[Data.SqlClient.SqlConnection]::new($b.ConnectionString);$tx=$null
try{$cn.Open();$tx=$cn.BeginTransaction([Data.IsolationLevel]::Serializable);$cmd=$cn.CreateCommand();$cmd.Transaction=$tx;$cmd.CommandTimeout=10;$cmd.CommandText="SELECT DB_NAME(),CONVERT(nvarchar(128),SERVERPROPERTY('ServerName')),ORIGINAL_LOGIN(),IS_SRVROLEMEMBER('sysadmin'),HAS_PERMS_BY_NAME(DB_NAME(),'DATABASE','CONTROL')";$r=$cmd.ExecuteReader();try{if(-not$r.Read()-or$r.GetString(0)-cne $cfg.database-or$r.GetString(1)-cne $cfg.server-or$r.GetString(2)-cne $cfg.sqlUser-or$r.GetInt32(3)-ne 0-or$r.GetInt32(4)-ne 0){throw 'BUSINESS_EFFECTS_BASELINE_IDENTITY'}}finally{$r.Close();$cmd.Dispose()}
$cmd=$cn.CreateCommand();$cmd.Transaction=$tx;$cmd.CommandTimeout=10;$cmd.CommandText=@'
DECLARE @p nvarchar(max);SELECT @p=profile_json FROM dbo.stage4_copy_manifest WHERE copy_id=@copy AND sealed=1;
SELECT N'customer' role,CONVERT(varchar(20),c.id) id,CONVERT(varchar(20),a.id) accountId,a.currency_code currency,CONVERT(varchar(60),CONVERT(decimal(28,8),c.balance)-CONVERT(decimal(28,8),a.current_balance)) residualExact8,s.beforeHash,s.accountBeforeHash,s.sourceWitnessHash,
CONVERT(bit,CASE WHEN s.beforeHash=CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT c.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2) AND s.accountBeforeHash=CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT a.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2) AND s.baselineBalanceExact8=a.current_balance THEN 1 ELSE 0 END) capturedNativeRowsMatch
FROM dbo.customers c JOIN OPENJSON(@p,'$.customers')WITH(id bigint,accountId bigint,beforeHash char(64),accountBeforeHash char(64),sourceWitnessHash char(64),baselineBalanceExact8 decimal(28,8),sourceKnown bit)s ON s.id=c.id JOIN dbo.party_currency_accounts a ON a.id=s.accountId AND a.customer_id=c.id AND a.supplier_id IS NULL WHERE s.sourceKnown=1 AND c.currency_code=a.currency_code AND CONVERT(decimal(38,8),c.balance)<>a.current_balance
UNION ALL
SELECT N'supplier',CONVERT(varchar(20),c.id),CONVERT(varchar(20),a.id),a.currency_code,CONVERT(varchar(60),CONVERT(decimal(28,8),c.balance)-CONVERT(decimal(28,8),a.current_balance)),s.beforeHash,s.accountBeforeHash,s.sourceWitnessHash,
CONVERT(bit,CASE WHEN s.beforeHash=CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT c.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2) AND s.accountBeforeHash=CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT a.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES)),2) AND s.baselineBalanceExact8=a.current_balance THEN 1 ELSE 0 END)
FROM dbo.suppliers c JOIN OPENJSON(@p,'$.suppliers')WITH(id bigint,accountId bigint,beforeHash char(64),accountBeforeHash char(64),sourceWitnessHash char(64),baselineBalanceExact8 decimal(28,8),sourceKnown bit)s ON s.id=c.id JOIN dbo.party_currency_accounts a ON a.id=s.accountId AND a.supplier_id=c.id AND a.customer_id IS NULL WHERE s.sourceKnown=1 AND c.currency_code=a.currency_code AND CONVERT(decimal(38,8),c.balance)<>a.current_balance
ORDER BY role,id,accountId
'@;$null=$cmd.Parameters.Add('@copy',[Data.SqlDbType]::UniqueIdentifier);$cmd.Parameters['@copy'].Value=[Guid]$cfg.copyContext.copyId;$r=$cmd.ExecuteReader();$rows=@();try{while($r.Read()){$entry=[ordered]@{};for($i=0;$i-lt 8;$i++){$entry[$r.GetName($i)]=$r.GetValue($i)};if($r.GetBoolean(8)-ne $true){throw 'BUSINESS_EFFECTS_BASELINE_NATIVE_PIN_DRIFT'};$rows+=$entry}}finally{$r.Close();$cmd.Dispose()};if($rows.Count-ne 37){throw 'BUSINESS_EFFECTS_BASELINE_FINITE37'}
$proof=[ordered]@{schemaVersion='melisa-business-effects-baseline-capture.v1';database=$cfg.database;server=$cfg.server;copyId=$cfg.copyContext.copyId;baseSealHash=$cfg.copyContext.sealHash;baseReadyPerformanceRevisionHash=$cfg.businessReadyPerformanceRevision.revisionHash;baselineResiduals=$rows;capturedNativeRowsMatch=$true;businessWrites=0;openingHumanAccepted=$false;recordedAt=[DateTime]::UtcNow.ToString('o')};[IO.File]::WriteAllText($out,($proof|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));@{file=$out;residuals=37;capturedNativeRowsMatch=$true;businessWrites=0;openingHumanAccepted=$false}|ConvertTo-Json -Compress
}finally{if($tx){$tx.Rollback();$tx.Dispose()};$cn.Dispose();$b.Clear();$cfg=$null}
